package net.officefloor.hq.app.holiday;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The holidays on a sheet. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/holidays")
@Validated
public class HolidayController {

    /** A holiday: its id and its date. */
    public record HolidayView(long id, LocalDate date) {
        static HolidayView of(SheetHoliday h) {
            return new HolidayView(h.getId(), h.getDate());
        }
    }

    /** A holiday asked: its date (YYYY-MM-DD). */
    public record HolidayRequest(@NotNull @Pattern(regexp = "\\s*\\d{4}-\\d{2}-\\d{2}\\s*") String date) {
        LocalDate dateValue() {
            return LocalDate.parse(date.trim());
        }
    }

    private final HolidayService service;

    public HolidayController(HolidayService service) {
        this.service = service;
    }

    @GetMapping
    public List<HolidayView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.holidays(sheetId.trim()).stream().map(HolidayView::of).toList();
    }

    @PostMapping
    public List<HolidayView> add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid HolidayRequest request) {
        String sheet = sheetId.trim();
        service.add(sheet, user.trim(), request.dateValue());
        return list(sheet);
    }
}
package net.officefloor.hq.app.holiday;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The holidays on a sheet. A claim's due-by is the terms-th business day after the date it counts from,
 * skipping every Saturday, Sunday and holiday on the sheet (see {@link #dueBy}); when a holiday is added
 * the due-by of every claim on the sheet is worked out again with the holidays then. */
@Service
public class HolidayService {

    private final SheetRepository sheets;
    private final SheetHolidayRepository holidays;
    private final ClaimRepository claims;
    private final RollupService rollup;
    private final Audit audit;

    public HolidayService(SheetRepository sheets, SheetHolidayRepository holidays, ClaimRepository claims,
            RollupService rollup, Audit audit) {
        this.sheets = sheets;
        this.holidays = holidays;
        this.claims = claims;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The sheet's holidays, earliest first. */
    @Transactional(readOnly = true)
    public List<SheetHoliday> holidays(String sheetId) {
        return holidays.findBySheetIdOrderByDateAsc(sheetId);
    }

    /** Add a holiday on {@code date}; refused when the date is already on the sheet's list. */
    @Transactional
    public SheetHoliday add(String sheetId, String by, LocalDate date) {
        sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
        if (holidays.existsBySheetIdAndDate(sheetId, date)) throw new HolidayTakenException();
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        SheetHoliday added = holidays.saveAndFlush(new SheetHoliday(sheetId, date));
        Set<LocalDate> off = offOn(sheetId);
        for (Claim claim : claims.findBySheetIdOrderByListedDescIdDesc(sheetId)) {
            LocalDate dueBy = dueBy(off, claim.getDueFrom(), claim.getTerms());
            if (!dueBy.equals(claim.getDueBy())) claim.setDueBy(dueBy);
        }
        claims.flush();
        audit.change("HOLIDAY_ADDED", sheetId, by, "date=" + date);
        rollup.recordSince(sheetId, by, before);
        return added;
    }

    /** The due-by of a claim counting from {@code from} with {@code terms}: the terms-th business day
     * after it, counting forward from the day after and skipping every Saturday, Sunday and holiday on
     * the sheet; with terms of 0, {@code from} itself. */
    @Transactional(readOnly = true)
    public LocalDate dueBy(String sheetId, LocalDate from, int terms) {
        return dueBy(offOn(sheetId), from, terms);
    }

    private Set<LocalDate> offOn(String sheetId) {
        return holidays.findBySheetIdOrderByDateAsc(sheetId).stream().map(SheetHoliday::getDate)
                .collect(Collectors.toSet());
    }

    private static LocalDate dueBy(Set<LocalDate> off, LocalDate from, int terms) {
        LocalDate on = from;
        for (int counted = 0; counted < terms;) {
            on = on.plusDays(1);
            if (isBusinessDay(off, on)) counted++;
        }
        return on;
    }

    private static boolean isBusinessDay(Set<LocalDate> off, LocalDate date) {
        DayOfWeek day = date.getDayOfWeek();
        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !off.contains(date);
    }
}
package net.officefloor.hq.app.holiday;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** A holiday asked for a date already on the sheet's list. */
@ResponseStatus(HttpStatus.CONFLICT)
public class HolidayTakenException extends RuntimeException {
}
package net.officefloor.hq.app.holiday;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A holiday on a sheet: a date no claim added from then on is due by. */
@Entity
@Table(name = "sheet_holiday")
public class SheetHoliday {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "holiday_date", nullable = false)
    private LocalDate date;

    protected SheetHoliday() {
    }

    public SheetHoliday(String sheetId, LocalDate date) {
        this.sheetId = sheetId;
        this.date = date;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public LocalDate getDate() {
        return date;
    }
}
package net.officefloor.hq.app.holiday;

import java.time.LocalDate;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface SheetHolidayRepository extends JpaRepository<SheetHoliday, Long> {

    List<SheetHoliday> findBySheetIdOrderByDateAsc(String sheetId);

    boolean existsBySheetIdAndDate(String sheetId, LocalDate date);
}
-- The holidays on a sheet, one row each: a claim's due-by fixed when it is added is moved past them.
CREATE TABLE sheet_holiday (
